	sbcs	x1,x23,x9
	sbcs	x3,x24,x10
	sbcs	xzr,    x25,xzr

	csel	x11,x19,x26,lo
	csel	x12,x20,x27,lo
	csel	x13,x21,x28,lo
	csel	x14,x22,x0,lo
	csel	x15,x23,x1,lo
	csel	x16,x24,x3,lo
	// ---- end __mul_mont_384

	ldr	x0,[x18,#-24]		// P
	ldp	x19,x20,[x0,#48]
	ldp	x21,x22,[x0,#64]
	ldp	x23,x24,[x0,#80]
	subs	x11,x11,x19
	sbcs	x12,x12,x20
	sbcs	x13,x13,x21
	sbcs	x14,x14,x22
	sbcs	x15,x15,x23
	sbcs	x16,x16,x24
	sbc	x3,xzr,xzr
	and	x25,x5,x3
	and	x26,x6,x3
	and	x27,x7,x3
	and	x28,x8,x3
	and	x17,x9,x3
	and	x3,x10,x3
	adds	x11,x11,x25
	adcs	x12,x12,x26
	adcs	x13,x13,x27
	adcs	x14,x14,x28
	adcs	x15,x15,x17
	adc	x16,x16,x3
	stp	x11,x12,[x2,#48]	// y'
	stp	x13,x14,[x2,#64]
	stp	x15,x16,[x2,#80]

	// key = bits 64..255 (limbs 1..3) of the even one of y', p - y'
	// (p is odd, so exactly one is even; a borrow only moves upward, so
	// limbs 0..3 of p - y' need no higher limb)
	subs	x19,x5,x11
	sbcs	x20,x6,x12
	sbcs	x21,x7,x13
	sbc	x22,x8,x14
	tst	x11,#1			// ne iff y' odd: take p - y'
	csel	x12,x20,x12,ne
	csel	x13,x21,x13,ne
	csel	x14,x22,x14,ne
	stp	x12,x13,[x2,#96]
	str	x14,[x2,#112]

	cmp	x18,x30
	b.ne	.Llane

	add	sp,sp,#144
	ldr	x18,[x29,#224]
	ldp	x19,x20,[x29,#16]
	ldp	x21,x22,[x29,#32]
	ldp	x23,x24,[x29,#48]
	ldp	x25,x26,[x29,#64]
	ldp	x27,x28,[x29,#80]
	ldp	x29,x30,[sp],#240
	ret
.size	side_lanes,.-side_lanes

